   323		\[
   324			\E_{u \in \F_q^m} \sum_a \bra{\hat\psi} (\hat{S}^W_{[g(u)=a]})_{\mathrm{B}\mathrm{B}'} \ot (K^u_a)_{\mathrm{A}\mathrm{B}''} \ket{\hat\psi} \geq 1 - O(\delta_G + \eps)\;.
   325		\]
   326		Expanding $K^u_a$ over pairs $(h, h'')$ of Pauli outcomes, a term of the left-hand side with outcomes $(g, h, h'')$ is constrained by $g(u) = g_h(u) + g_{h''}(u) = g_{h + h''}(u)$, by the linearity of the encoding \eqref{eq:low-degree-encoding-definition}. If $g$ is not an encoding then $g \neq g_{h+h''}$, and both are polynomials of total degree at most $md$, so the constraint holds for at most an $md/q$ fraction of $u$ (Lemma~\ref{lem:schwartz-zippel-total-degree}). Since all terms are nonnegative and, for each $g$, the operators of the $(h,h'')$-sum add up to the identity, it follows that
   327		\begin{equation}\label{eq:qld-nonencoding-mass}
   328		\sum_{g \,\text{not an encoding}} \bra{\hat\psi} (\hat{S}^W_g)_{\mathrm{B}\mathrm{B}'} \ket{\hat\psi} \,\leq\, O(\delta_G + \eps) + \frac{md}{q} \,\leq\, \delta_P\;,
   329		\end{equation}
   330		and symmetrically with the registers $\mathrm{A}\mathrm{A}'$ in place of $\mathrm{B}\mathrm{B}'$. (If $d = 0$, every element of $\mathrm{ideg}_{d,m}(\F_q)$ is constant, hence an encoding, and the left-hand side vanishes.)
   331	
   332		For the first item, in the case where $M^{(\mathrm{Point},W),u}_a$ acts on register $\mathrm{A}$ and $\tilde{M}^{W,\mathrm{ind}_m(u)}_a$ on $\mathrm{B}\mathrm{B}'\mathrm{B}''$, expanding \eqref{eq:tilde_M} and \eqref{eq:def-tauwu} and using the convolution form of the combined projectors $\hat{M}^{(\mathrm{Point},W),u}_a$ (Definition~\ref{def:expanded-point-measurement}) gives the exact identity
   333		\[
   334			\E_{u \in \F_q^m} \sum_a \bra{\hat\psi} M^{(\mathrm{Point},W),u}_a \ot \tilde{M}^{W,\mathrm{ind}_m(u)}_a \ket{\hat\psi}
   335			= \E_{u \in \F_q^m} \sum_g \bra{\hat\psi} (\hat{M}^{(\mathrm{Point},W),u}_{\mathrm{Dec}(g) \cdot \mathrm{ind}_m(u)})_{\mathrm{A}\mathrm{B}''} \ot (\hat{S}^W_g)_{\mathrm{B}\mathrm{B}'} \ket{\hat\psi}\;.
   336		\]
   337		For encodings $g$ the subscript $\mathrm{Dec}(g) \cdot \mathrm{ind}_m(u)$ equals $g(u)$; discarding the (nonnegative) terms with $g$ not an encoding and reinstating the corresponding terms with subscript $g(u)$, each of which is at most $\bra{\hat\psi} (\hat{S}^W_g)_{\mathrm{B}\mathrm{B}'} \ket{\hat\psi}$, shows that the right-hand side is at least
   338		\[
   339			\E_{u \in \F_q^m} \sum_g \bra{\hat\psi} (\hat{M}^{(\mathrm{Point},W),u}_{g(u)})_{\mathrm{A}\mathrm{B}''} \ot (\hat{S}^W_g)_{\mathrm{B}\mathrm{B}'} \ket{\hat\psi} - \delta_P
   340			\geq 1 - \delta_P
   341		\]
   342		by \eqref{eq:qld-nonencoding-mass} and Lemma~\ref{lem:qld-4-7}, and the register-interchanged relation follows analogously. For the second item one first shows that, on average over uniformly random $\tilde{u} \in \F_q^M$,
   343		\begin{equation}\label{eq:qld-pulling-cons}
   344			\bigl( \tilde{M}^{W,\tilde{u}}_a \bigr)_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \approx_{\delta_P} \bigl( \tilde{M}^{W,\tilde{u}}_a \bigr)_{\mathrm{B}\mathrm{B}'\mathrm{B}''}\;:
   345		\end{equation}
